 "path": "/account/activity",
 "method": "GET",
 "description": "Show a history of your expenses and payments combined.",
 "parameters": [
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from splitwise app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "show_expenses",
   "type": "boolean",
   "required": false,
   "description": "Whether to show expenses in the history.",
   "default": true,
   "constraints": []
  },
  {
   "name": "show_payments",
   "type": "boolean",
   "required": false,
   "description": "Whether to show payments in the history.",
   "default": true,
   "constraints": []
  },
  {
   "name": "page_index",
   "type": "integer",
   "required": false,
   "description": "The index of the page to return.",
   "default": 0,
   "constraints": [
    "value >= 0.0"
   ]
  },
  {
   "name": "page_limit",
   "type": "integer",
   "required": false,
   "description": "The maximum number of results to return per page.",
   "default": 5,
   "constraints": [
    "value >= 1.0, <= 20.0"
   ]
  },
  {
   "name": "sort_by",
   "type": "string",
   "required": false,
