    },
    "owed_by": [
     {
      "name": "string",
      "email": "user@example.com",
      "amount": 0.0
     }
    ],
    "description": "string",
    "group_id": 1,
    "group_name": "string",
    "created_at": "2019-01-01T00:00:00"
   }
  ],
  "failure": {
   "message": "string"
  }
 }
}

